/**
 * The dashboard's typed client for the control-plane REST surface. One
 * module owns the response wrapper contract: success `{ data }`, failure
 * `{ error: { type, message } }`. Every other module speaks in domain
 * types; network details stop here.
 */

export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly type: string,
    message: string,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

export type PublicConfig = {
  readonly oauth: string[];
  readonly turnstileSiteKey: string | null;
  /** Public origin of the data plane ("https://api.lynk.io"); the Anthropic
   *  base URL clients use is `${apiBaseUrl}/v1/anthropic`. */
  readonly apiBaseUrl: string;
};

export type Me = {
  readonly userId: string;
  readonly email: string;
  readonly emailVerified: boolean;
  readonly orgs: {
    readonly id: string;
    readonly name: string;
    readonly type: string;
    readonly planCode: string;
    readonly role: "owner" | "admin" | "member";
    /** Plan ceilings, when the org's plan code is registered — surfaces
     *  that explain headroom ("2 of 10 used") read these. */
    readonly maxEndpoints?: number | undefined;
    readonly maxKeys?: number | undefined;
  }[];
};

export type EndpointStatus = "pending" | "active" | "failed" | "disabled";

export type CheckGate = {
  readonly name: string;
  readonly passed: boolean;
  readonly ms: number;
