//! The questions a deployment will answer about its own counters.
//!
//! Reading an Analytics Engine dataset means SQL, and the credential
//! that runs it is a Cloudflare API token. A worker holding one must
//! never let a caller compose the query: a UI that could send SQL would
//! be an injection surface with an account token behind it, and the
//! token's narrow scope bounds the damage without preventing it.
//!
//! So a caller does not send a query. It chooses one, from here. Every
//! part of the emitted SQL is either a literal or a value drawn from a
//! closed enum, so there is no path by which caller text reaches the
//! statement at all. That is a stronger claim than escaping, and the
//! tests below are what hold it: a hostile string simply fails to parse
//! into a choice.

/// Which family of counted thing to report on.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QuerySubject {
    /// Objects served.
    Reads,
    /// Objects stored, or refused.
    Writes,
    /// Presence probes, one per push.
    Probes,
}

impl QuerySubject {
    /// Parse a caller's choice. Anything else is not a choice.
    #[must_use]
    pub fn parse(text: &str) -> Option<Self> {
        match text {
            "reads" => Some(Self::Reads),
            "writes" => Some(Self::Writes),
            "probes" => Some(Self::Probes),
            _ => None,
        }
    }

    /// The `index1` value this subject selects on.
    const fn index(self) -> &'static str {
        match self {
            Self::Reads => "read",
            Self::Writes => "write",
            Self::Probes => "probe",
        }
    }
}

/// Which column to group by. One per dimension the writers fill, and
/// nothing else: the mapping to a blob position lives here so a caller
/// never names one.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueryDimension {
    /// What the thing was.
    Kind,
    /// How it went.
    Outcome,
    /// Who asked.
    Actor,
    /// Which repository's workflow run.
    Repository,
    /// Which ref that run was on.
    Reference,
    /// Which lease.
    Project,
}

impl QueryDimension {
    /// Parse a caller's choice. Anything else is not a choice.
    #[must_use]
    pub fn parse(text: &str) -> Option<Self> {
        match text {
            "kind" => Some(Self::Kind),
            "outcome" => Some(Self::Outcome),
            "actor" => Some(Self::Actor),
            "repository" => Some(Self::Repository),
            "reference" => Some(Self::Reference),
            "project" => Some(Self::Project),
            _ => None,
        }
    }

    /// The blob column this dimension lives in, matching
    /// `stats::StatPoint::blobs`.
    const fn column(self) -> &'static str {
        match self {
            Self::Kind => "blob1",
            Self::Outcome => "blob2",
            Self::Actor => "blob3",
            Self::Repository => "blob4",
            Self::Reference => "blob5",
            Self::Project => "blob6",
        }
    }
}

/// How far back to look.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueryWindow {
    /// The last day.
    Day,
    /// The last week.
    Week,
    /// The last month.
    Month,
}

impl QueryWindow {
    /// Parse a caller's choice, defaulting to a day when unstated.
    #[must_use]
    pub fn parse(text: Option<&str>) -> Option<Self> {
        match text {
            None | Some("day") => Some(Self::Day),
            Some("week") => Some(Self::Week),
            Some("month") => Some(Self::Month),
            _ => None,
        }
    }

    /// The interval's day count. An integer, so it is a literal in the
    /// emitted SQL rather than caller text.
    const fn days(self) -> u8 {
        match self {
            Self::Day => 1,
            Self::Week => 7,
            Self::Month => 30,
        }
    }
}

/// One chosen question.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StatsQuery {
    /// What to count.
    pub subject: QuerySubject,
    /// What to group by.
    pub dimension: QueryDimension,
    /// How far back.
    pub window: QueryWindow,
}

/// The rows one answer may carry. A dimension with more distinct values
/// than this is a dimension nobody reads to the bottom of, and an
/// unbounded answer is an unbounded response body.
pub const STATS_ROWS_MAX: u32 = 100;

impl StatsQuery {
    /// The SQL for this question against one dataset.
    ///
    /// `dataset` is the deployment's own name from its configuration,
    /// never a caller's. Every other interpolation is a `&'static str`
    /// or an integer from an enum, which is why no escaping appears
    /// here: there is nothing to escape.
    #[must_use]
    pub fn sql(&self, dataset: &str) -> String {
        format!(
            "SELECT {dimension} AS dimension, \
             SUM(_sample_interval * double1) AS count, \
             SUM(_sample_interval * double2) AS bytes \
             FROM {dataset} \
             WHERE index1 = '{index}' AND timestamp > NOW() - INTERVAL '{days}' DAY \
             GROUP BY dimension ORDER BY count DESC LIMIT {STATS_ROWS_MAX}",
            dimension = self.dimension.column(),
            index = self.subject.index(),
            days = self.window.days(),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_chosen_question_reads_as_written() {
        let query = StatsQuery {
            subject: QuerySubject::Writes,
            dimension: QueryDimension::Repository,
            window: QueryWindow::Week,
        };
        let sql = query.sql("cachet_production");
        assert!(sql.contains("blob4 AS dimension"), "{sql}");
        assert!(sql.contains("index1 = 'write'"), "{sql}");
        assert!(sql.contains("INTERVAL '7' DAY"), "{sql}");
        assert!(sql.contains("FROM cachet_production"), "{sql}");
        assert!(sql.ends_with("LIMIT 100"), "{sql}");
    }

    #[test]
    fn nothing_a_caller_writes_can_reach_the_statement() {
        // Every hostile shape a query string could carry. None of them
        // parse into a choice, so none of them are ever formatted: the
        // defence is the absence of a path, not an escape.
        for hostile in [
            "actor'; DROP TABLE x; --",
            "blob1, blob2",
            "1=1",
            "kind UNION SELECT 1",
            "",
            "KIND",
            "../kind",
        ] {
            assert!(QueryDimension::parse(hostile).is_none(), "{hostile}");
            assert!(QuerySubject::parse(hostile).is_none(), "{hostile}");
            assert!(QueryWindow::parse(Some(hostile)).is_none(), "{hostile}");
        }
    }

    #[test]
    fn every_choice_maps_to_one_column_and_back() {
        // A dimension whose column collided with another would silently
        // answer the wrong question.
        let all = [
            QueryDimension::Kind,
            QueryDimension::Outcome,
            QueryDimension::Actor,
            QueryDimension::Repository,
            QueryDimension::Reference,
            QueryDimension::Project,
        ];
        let mut columns: Vec<&str> = all.iter().map(|one| one.column()).collect();
        columns.sort_unstable();
        columns.dedup();
        assert_eq!(
            columns.len(),
            all.len(),
            "every dimension has its own column"
        );
    }

    #[test]
    fn an_unstated_window_is_a_day_and_a_wrong_one_is_refused() {
        assert_eq!(QueryWindow::parse(None), Some(QueryWindow::Day));
        assert_eq!(QueryWindow::parse(Some("month")), Some(QueryWindow::Month));
        assert_eq!(QueryWindow::parse(Some("decade")), None);
    }
}

//! What a deployment counts about itself.
//!
//! Every interesting request writes one data point to an Analytics
//! Engine dataset: what happened, to what, for whom, and how much. The
//! worker's event log already says the same things, but a log line is
//! something an operator greps during an incident. These are for the
//! questions asked afterwards and continuously: what is the hit rate,
//! which repository pushes the most bytes, is CI reading more than
//! laptops, did last night's collector actually delete anything.
//!
//! The schema lives here, in the pure crate, because a data point is
//! positional: `blob3` means an outcome only because every writer agrees
//! it does, and a query written against the wrong position is silently
//! wrong rather than broken. One type defines the positions, every
//! writer fills that type, and docs/DEPLOY.md's queries name the same
//! columns.

/// Which family of thing happened. The dataset's index, so it is also
/// the sampling key: coarse on purpose.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StatEvent {
    /// An object was served, or was not.
    Read,
    /// An object was stored, or was refused.
    Write,
    /// A push asked what the cache already holds.
    Probe,
    /// The collector ran.
    Collect,
    /// A credential was issued or refused.
    Auth,
}

impl StatEvent {
    /// The name the dataset stores and a query groups by.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Read => "read",
            Self::Write => "write",
            Self::Probe => "probe",
            Self::Collect => "collect",
            Self::Auth => "auth",
        }
    }
}

/// Who the request was. Reads split three ways and the split is the
/// point: a deployment whose reads are all CI is a different thing from
/// one people substitute from daily.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StatActor {
    /// A workflow run, holding an OIDC token.
    Ci,
    /// A person's machine, holding a credential this deployment issued.
    Laptop,
    /// A browser session.
    Browser,
    /// Nobody: the request carried no usable credential.
    Anonymous,
}

impl StatActor {
    /// The name the dataset stores.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Ci => "ci",
            Self::Laptop => "laptop",
            Self::Browser => "browser",
            Self::Anonymous => "anonymous",
        }
    }
}

/// Who made a request, with whatever the credential knew about them.
///
/// Carried as one value so a caller cannot pass the actor and forget the
/// run it belonged to: for a workflow those two are the same fact, and a
/// read counted without its repository cannot be grouped by one.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct StatCaller {
    /// The caller class.
    pub actor: Option<StatActor>,
    /// `owner/repo` when a workflow run, else empty.
    pub repository: String,
    /// That run's ref, else empty.
    pub reference: String,
}

impl StatCaller {
    /// A caller with nothing known about it.
    #[must_use]
    pub fn anonymous() -> Self {
        Self {
            actor: Some(StatActor::Anonymous),
            ..Self::default()
        }
    }

    /// A person at a machine.
    #[must_use]
    pub fn laptop() -> Self {
        Self {
            actor: Some(StatActor::Laptop),
            ..Self::default()
        }
    }

    /// A browser session.
    #[must_use]
    pub fn browser() -> Self {
        Self {
            actor: Some(StatActor::Browser),
            ..Self::default()
        }
    }

    /// A workflow run, which knows where it ran.
    #[must_use]
    pub fn ci(repository: &str, reference: &str) -> Self {
        Self {
            actor: Some(StatActor::Ci),
            repository: repository.to_string(),
            reference: reference.to_string(),
        }
    }
}

/// One data point, with every dimension a query may group by.
///
/// Absent dimensions are the empty string rather than omitted: a data
/// point's blobs are positional, so a writer that skipped one would
/// shift every dimension after it.
#[derive(Debug, Clone, PartialEq)]
pub struct StatPoint {
    /// The family of thing that happened.
    pub event: StatEvent,
    /// What it happened to: `narinfo`, `nar`, `part`, `lease`, `sweep`.
    pub kind: String,
    /// How it went: `edge_hit`, `bucket_hit`, `miss`, `stored`, or the
    /// error code of a refusal, so a rejection rate is one query.
    pub outcome: String,
    /// Who asked.
    pub actor: StatActor,
    /// `owner/repo` when a workflow run is the caller, else empty.
    pub repository: String,
    /// The git ref of that run, else empty.
    pub reference: String,
    /// The lease name a push writes under, else empty.
    pub project: String,
    /// How many things this point counts. Almost always one; a batch
    /// says how big it was.
    pub count: f64,
    /// Bytes moved, where the answer is bytes.
    pub bytes: f64,
}

impl StatPoint {
    /// A point with every dimension empty, for a writer to fill.
    #[must_use]
    pub fn new(event: StatEvent, kind: &str, outcome: &str) -> Self {
        Self {
            event,
            kind: kind.to_string(),
            outcome: outcome.to_string(),
            actor: StatActor::Anonymous,
            repository: String::new(),
            reference: String::new(),
            project: String::new(),
            count: 1.0,
            bytes: 0.0,
        }
    }

    /// Name the caller, and whatever their credential knew about them.
    #[must_use]
    pub fn by(mut self, caller: &StatCaller) -> Self {
        self.actor = caller.actor.unwrap_or(StatActor::Anonymous);
        self.repository.clone_from(&caller.repository);
        self.reference.clone_from(&caller.reference);
        self
    }

    /// Name the workflow run this came from.
    #[must_use]
    pub fn from_run(mut self, repository: &str, reference: &str) -> Self {
        self.repository = repository.to_string();
        self.reference = reference.to_string();
        self
    }

    /// Name the lease this concerns.
    #[must_use]
    pub fn for_project(mut self, project: &str) -> Self {
        self.project = project.to_string();
        self
    }

    /// Say how many, and how much.
    #[must_use]
    pub fn measuring(mut self, count: u64, bytes: u64) -> Self {
        self.count = exact(count);
        self.bytes = exact(bytes);
        self
    }

    /// The blob columns, in the order every query names them.
    #[must_use]
    pub fn blobs(&self) -> [&str; 6] {
        [
            self.kind.as_str(),
            self.outcome.as_str(),
            self.actor.name(),
            self.repository.as_str(),
            self.reference.as_str(),
            self.project.as_str(),
        ]
    }

    /// The double columns, in the order every query names them.
    #[must_use]
    pub fn doubles(&self) -> [f64; 2] {
        [self.count, self.bytes]
    }
}

/// A count as the dataset stores it.
///
/// Analytics Engine holds doubles, whose mantissa is 53 bits, so a value
/// past nine petabytes would round. Nothing here is nine petabytes, and
/// a number claiming to be is worth capping rather than rounding: a
/// total that saturates is visibly wrong, where one that rounds is
/// quietly wrong.
#[must_use]
pub fn exact(value: u64) -> f64 {
    /// Two to the fifty-third: the largest integer an f64 holds exactly.
    const EXACT_MAX: u64 = 9_007_199_254_740_992;
    #[allow(
        clippy::cast_precision_loss,
        reason = "clamped to 2^53, below which f64 is exact"
    )]
    {
        value.min(EXACT_MAX) as f64
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_column_order_is_the_documented_one() {
        // docs/DEPLOY.md's queries name blob1..blob6 and double1..double2
        // in exactly this order. A writer that reordered them would make
        // every committed query silently wrong, so the order is asserted
        // rather than assumed.
        let point = StatPoint::new(StatEvent::Read, "narinfo", "edge_hit")
            .by(&StatCaller::ci("nox-systems/cachet", "refs/heads/main"))
            .for_project("nox-systems-cachet")
            .measuring(1, 4_096);
        assert_eq!(
            point.blobs(),
            [
                "narinfo",
                "edge_hit",
                "ci",
                "nox-systems/cachet",
                "refs/heads/main",
                "nox-systems-cachet",
            ]
        );
        // why: bit equality. The claim is that these land exactly, not
        // approximately, which is the whole reason `exact` clamps.
        assert_eq!(
            point.doubles().map(f64::to_bits),
            [1.0_f64, 4_096.0].map(f64::to_bits)
        );
        assert_eq!(point.event.name(), "read");
    }

    #[test]
    fn an_unfilled_dimension_is_empty_and_not_missing() {
        // Positional columns: skipping one would shift the rest.
        let point = StatPoint::new(StatEvent::Probe, "probe", "answered");
        assert_eq!(point.blobs().len(), 6);
        assert_eq!(point.blobs()[3], "", "no repository is the empty string");
        assert_eq!(point.actor, StatActor::Anonymous);
    }

    #[test]
    fn counts_clamp_rather_than_round() {
        assert_eq!(exact(0).to_bits(), 0.0_f64.to_bits());
        assert_eq!(exact(4_096).to_bits(), 4_096.0_f64.to_bits());
        // Past the mantissa, the value stops rather than drifting.
        assert_eq!(
            exact(u64::MAX).to_bits(),
            9_007_199_254_740_992.0_f64.to_bits()
        );
    }

    #[test]
    fn every_actor_and_event_names_itself() {
        for actor in [
            StatActor::Ci,
            StatActor::Laptop,
            StatActor::Browser,
            StatActor::Anonymous,
        ] {
            assert!(!actor.name().is_empty());
        }
        for event in [
            StatEvent::Read,
            StatEvent::Write,
            StatEvent::Probe,
            StatEvent::Collect,
            StatEvent::Auth,
        ] {
            assert!(!event.name().is_empty());
        }
    }
}

