        assert_eq!(filled[6].count, 5.0);
        assert_eq!(filled[3].count, 2.0);
        assert_eq!(filled[3].bytes, 20.0);
        assert!(
            filled.iter().all(|point| point.count != 99.0),
            "a bucket outside the window is not in the answer"
        );
    }
}
